import React from 'react';

function App() {
  return (
    <div
      style={{
        minHeight: '100vh',
        background: '#F8F5EF',
        fontFamily: 'Arial, sans-serif',
      }}
    >
      <header
        style={{
          background: '#173F35',
          color: 'white',
          padding: '25px',
          textAlign: 'center',
        }}
      >
        <h1>CraftLanka</h1>
        <p>Discover Sri Lankan Handmade Crafts</p>
      </header>

      <main style={{ padding: '50px 20px', textAlign: 'center' }}>
        <h2>Welcome to CraftLanka</h2>
        <p>Support local artisans and explore traditional craftsmanship.</p>
      </main>
    </div>
  );
}

export default App;
